from pathlib import Path
import base64
ROOT=Path(__file__).resolve().parents[1];VERSION='1.2';data=(ROOT/'src/data.js').read_text(encoding='utf-8');packs=(ROOT/'src/v120/quality-packs.js').read_text(encoding='utf-8')
css='''*{box-sizing:border-box}:root{color-scheme:dark;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#08080a;color:#f5f5f7}body{margin:0}.bar{position:sticky;top:10px;z-index:5;margin:10px;display:flex;gap:7px;padding:9px;border:1px solid #33343a;background:rgba(28,28,32,.72);backdrop-filter:blur(24px);border-radius:18px}.bar b{margin-right:auto;padding:8px}.bar button{border:1px solid #38383f;border-radius:10px;background:#18181c;color:#eee;padding:8px 11px}.bar button.active{background:var(--client);color:#090909}.wrap{max-width:1400px;margin:auto;padding:36px 5vw 80px}.hero{padding:34px 0;border-bottom:1px solid #2d2d32}.hero span{color:var(--client);font-size:12px;text-transform:uppercase}.hero h1{font-size:clamp(42px,6vw,78px);line-height:.94;letter-spacing:-.055em;margin:12px 0}.hero p{max-width:920px;color:#c7c7cc;font-size:16px;line-height:1.6}.stats,.grid{display:grid;gap:12px}.stats{grid-template-columns:repeat(4,1fr);margin:16px 0}.stats div,.card{border:1px solid #2d2d32;background:#141418;border-radius:20px;padding:20px}.stats b{font-size:32px;display:block}.stats small,.card p,.card li{color:#aaaab2}.grid{grid-template-columns:repeat(2,1fr)}.card h2{font-size:24px}.formats details{border-top:1px solid #2d2d32;padding:10px 0}.formats summary{cursor:pointer}.contents article{display:grid;grid-template-columns:1fr auto;gap:7px;border-top:1px solid #2d2d32;padding:10px 0}.contents small{grid-column:1/-1;color:#8e8e93}@media(max-width:760px){.stats,.grid{grid-template-columns:1fr}.bar{overflow:auto}.bar b{display:none}}'''
script=r'''const D=ABRAXAS_DATA;let active='abraxas';const E=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));function render(){const c=D.clients.find(x=>x.id===active)||D.clients[0],q=c.qualityPack||{},rows=D.contents.filter(x=>x.clientId===c.id);document.documentElement.style.setProperty('--client',c.accent);document.querySelectorAll('[data-client]').forEach(b=>b.classList.toggle('active',b.dataset.client===active));document.getElementById('view').innerHTML=`<section class="hero"><span>${E(c.category||'Marca')}</span><h1>${E(c.name)}</h1><p>${E(c.brandCore?.core||'')}</p></section><div class="stats"><div><b>${c.pillars?.length||0}</b><small>Pilares</small></div><div><b>${c.patterns?.length||0}</b><small>Formatos</small></div><div><b>${c.copyProfiles?.length||0}</b><small>Copy profiles</small></div><div><b>${rows.length}</b><small>Contents</small></div></div><div class="grid"><article class="card"><h2>Qué es</h2><ul>${(q.whatIs||[]).map(x=>`<li>${E(x)}</li>`).join('')}</ul></article><article class="card"><h2>Qué no es</h2><ul>${(q.whatIsNot||c.brandCore?.boundaries||[]).map(x=>`<li>${E(x)}</li>`).join('')}</ul></article><article class="card"><h2>Quality Gates</h2><ul>${(q.qualityGates||[]).map(x=>`<li>${E(x)}</li>`).join('')}</ul></article><article class="card"><h2>Visual / voz</h2><pre style="white-space:pre-wrap;color:#c7c7cc">${E(JSON.stringify(q.visual||{},null,2))}</pre><p>${E((q.voice||[]).join(' · '))}</p></article><article class="card formats"><h2>Formatos</h2>${(c.patterns||[]).map(p=>`<details><summary><b>${E(p.name)}</b></summary><p>Estructura: ${E((p.structure||[]).map(x=>typeof x==='string'?x:x.name).join(' → '))}</p><p>${E(p.visualRules||'')}</p></details>`).join('')}</article><article class="card contents"><h2>Contenidos</h2>${rows.map(x=>`<article><b>${E(x.title)}</b><span>${E(x.lifecycle)}</span><small>${E(x.summary||'')}</small></article>`).join('')}</article><article class="card" style="grid-column:1/-1"><h2>Source Truth</h2><ul>${[...(q.sourceTruth||[]),...(c.sources||[])].map(x=>`<li>${E(x)}</li>`).join('')}</ul></article></div>`}document.addEventListener('click',e=>{const b=e.target.closest('[data-client]');if(b){active=b.dataset.client;render()}});render();'''
html='<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ABRAXAS Client Intelligence v1.2</title><style>'+css+'</style></head><body><header class="bar"><b>ABRAXAS · Client Intelligence v1.2</b>'+''.join(f'<button data-client="{id}">{name}</button>' for id,name in [('abraxas','ABRAXAS'),('joc','JOC'),('moka','Moka Bio'),('inenergy','INENERGY')])+'</header><main class="wrap" id="view"></main><script>'+data+'</script><script>'+packs+'</script><script>'+script+'</script></body></html>'
out=ROOT/f'ABRAXAS_Client_Intelligence_v{VERSION}.html';out.write_text(html,encoding='utf-8');(ROOT/'deliverables').mkdir(exist_ok=True);(ROOT/f'deliverables/ABRAXAS_Client_Intelligence_v{VERSION}.html').write_text(html,encoding='utf-8');print(out)
